"""#764: artifact publication is generated by the UoW, not the legacy writer."""

from __future__ import annotations

import importlib.util
import sys
from pathlib import Path

import pytest

LIB = Path(__file__).resolve().parents[1] / "lib"
if str(LIB) not in sys.path:
    sys.path.insert(0, str(LIB))


def _state_module():
    path = Path(__file__).resolve().parents[1] / "bin" / "mission-state.py"
    spec = importlib.util.spec_from_file_location("issue764_state", path)
    module = importlib.util.module_from_spec(spec)
    assert spec and spec.loader
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    return module


@pytest.mark.parametrize(
    "sid",
    ("", "plain", ".hidden", ". foo", " leading", "a/b", r"a\\b", "ends "),
)
def test_artifact_rule_accepts_every_sanitized_session_segment(sid):
    from mission_kernel.projection_path import (
        ProjectionRejection,
        resolve_internal_artifact_path,
    )

    segment = _state_module()._sanitize_sid(sid)
    resolved = resolve_internal_artifact_path(
        Path(f".mission-state/artifacts/{segment}/mission-artifact.md"),
        root_name=".mission-state",
    )
    assert not isinstance(resolved, ProjectionRejection)


