def test_authorisation_is_bound_to_command_and_effect_field():
    from mission_application.evidence_publication import (
        EvidencePublicationError,
        authorize_generated_destinations,
    )

    artifact = ".mission-state/artifacts/test/mission-artifact.md"
    for command in (
        "initialize-artifact",
        "render-artifact",
        "record-artifact-publication",
    ):
        authorize_generated_destinations(
            (artifact,), command_type=command, field="effect"
        )
    authorize_generated_destinations(
        (artifact,), command_type="export-artifact", field="artifact_effect"
    )
    for command, field in (("export-artifact", "export_effect"), ("update-progress", "effect")):
        with pytest.raises(EvidencePublicationError) as caught:
            authorize_generated_destinations(
                (artifact,), command_type=command, field=field
            )
        assert caught.value.code == "publication-destination-unauthorized"


